import json,collections,statistics as s
q=collections.Counter(); lat={'pre':[],'post':[]}
for l in open('app.log'):
    d=json.loads(l)
    if d['service']!='cart': continue
    rid=d.get('request_id')
    if 'sku_id = ?' in d['msg']: q[rid]+=1
    if 'request_end' in d['msg'] and d['ts']>='2026-04-22T14:00' and d['ts']<'2026-04-22T15:00':
        k='pre' if d['ts']<'2026-04-22T14:16:45' else 'post'
        lat[k].append(d['latency_ms'])
for k,v in lat.items(): print(k,len(v),'median',s.median(v),'max',max(v))
print('requests with per-row queries:',len(q),'median per-row queries/request:',s.median(q.values()),'max:',max(q.values()))
